// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 firstAmount, uint256 secondAmount) internal {
        firstAmount = bound(firstAmount, 0, 1000000000000000000000000000000);
        secondAmount = bound(secondAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(firstAmount > 0 && secondAmount > 0);
        vm.assume(address(this).balance >= firstAmount + secondAmount);
        try c.Deposit{value: firstAmount}() {} catch { return; }
        try c.Deposit{value: secondAmount}() {} catch { return; }
        assertTrue(c.balances(address(this)) == firstAmount + secondAmount);
    }

    function testFuzz_run(uint256 firstAmount, uint256 secondAmount) public {
        _run(firstAmount, secondAmount);
    }

    receive() external payable {}
}
